import Foundation

public enum BundledModData {
    public static let patchFileName: String = "Assembly-CSharp-patch.bytes"
    public static let configFileName: String = "localConfig.json"
    public static let patchByteSize: Int = 97080
    public static let configByteSize: Int = 40
    
    /// Du lieu localConfig.json nhung cung
    public static var localConfigData: Data {
        if let url = Bundle.main.url(forResource: "localConfig", withExtension: "json") ??
                     Bundle.main.url(forResource: "localconfig", withExtension: "json") {
            if let d = try? Data(contentsOf: url), !d.isEmpty {
                return d
            }
        }
        if let d = Data(base64Encoded: "eyJ0ZXN0Q29kZVBhdGNoIjp0cnVlLCJyZXNldEd1ZXN0Ijp0cnVlfQ==") {
            return d
        }
        return Data("{\"testCodePatch\":true,\"resetGuest\":true}\n".utf8)
    }
    
    /// Du lieu Assembly-CSharp-patch.bytes nhung cung (97,080 bytes)
    public static var patchData: Data {
        // 1. Doc tu Bundle resource
        if let url = Bundle.main.url(forResource: "Assembly-CSharp-patch", withExtension: "bytes") ??
                     Bundle.main.url(forResource: "Assembly-CSharp.patch", withExtension: "bytes") {
            if let d = try? Data(contentsOf: url), d.count > 1000 {
                return d
            }
        }
        
        // 2. Doc tu thu muc bundle goc
        let bundleURL = Bundle.main.bundleURL
        let directFile = bundleURL.appendingPathComponent("Assembly-CSharp-patch.bytes")
        if let d = try? Data(contentsOf: directFile), d.count > 1000 {
            return d
        }
        
        // 3. Fallback du lieu Base64 nhung cung trong binary
        if let d = Data(base64Encoded: embeddedPatchBase64) {
            return d
        }
        
        return Data()
    }
    
    private static let embeddedPatchBase64: String = ""
}
